            if (eq != string::npos) {
                string key = urlDecode(pair.substr(0, eq));
                string value = urlDecode(pair.substr(eq + 1));
                data[key] = value;
            }
            pos = end + 1;
        }
        return data;
    }

    HttpRequest parseRequest(const string& rawRequest) {
        HttpRequest req;
        istringstream iss(rawRequest);
        string line;

        // Parse request line
        getline(iss, line);
        if (!line.empty() && line.back() == '\r') line.pop_back();
        istringstream lineStream(line);
        lineStream >> req.method >> req.path;

        // Parse query string
        size_t qpos = req.path.find('?');
        if (qpos != string::npos) {
            req.query = req.path.substr(qpos + 1);
            req.path = req.path.substr(0, qpos);
        }

        // Parse headers
        while (getline(iss, line) && line != "\r" && !line.empty()) {
            if (!line.empty() && line.back() == '\r') line.pop_back();
            size_t colon = line.find(':');
            if (colon != string::npos) {
                string key = line.substr(0, colon);
                string value = line.substr(colon + 1);
                // Trim leading space from value
                if (!value.empty() && value[0] == ' ') value = value.substr(1);
                req.headers[key] = value;
            }
        }

        // Parse cookies
        auto cookieIt = req.headers.find("Cookie");
        if (cookieIt != req.headers.end()) {
            req.cookies = parseCookies(cookieIt->second);
        }

        // Parse body if Content-Length exists
        auto clIt = req.headers.find("Content-Length");
        if (clIt != req.headers.end()) {
            int contentLength = stoi(clIt->second);
            if (contentLength > 0) {
                vector<char> buffer(contentLength + 1);
                iss.read(buffer.data(), contentLength);
                buffer[contentLength] = '\0';
                req.body = string(buffer.data());

                auto ctIt = req.headers.find("Content-Type");
                if (ctIt != req.headers.end() && ctIt->second.find("application/x-www-form-urlencoded") != string::npos) {
                    req.form_data = parseFormData(req.body);
                }
            }
        }

        return req;
    }

    string buildResponse(int statusCode, const string& statusText, const string& contentType,
                        const string& body, const map<string, string>& additionalHeaders = {}) {
        stringstream response;
        response << "HTTP/1.1 " << statusCode << " " << statusText << "\r\n";
        response << "Content-Type: " << contentType << "\r\n";
        response << "Content-Length: " << body.size() << "\r\n";
        response << "Connection: close\r\n";

        for (const auto& header : additionalHeaders) {
            response << header.first << ": " << header.second << "\r\n";
        }

        response << "\r\n";
        response << body;
        return response.str();
    }

    string getSessionCookie(const string& sessionId) {
        // Secure, HttpOnly, SameSite=Strict
        return "Set-Cookie: session_id=" + sessionId + "; Path=/; HttpOnly; SameSite=Strict; Max-Age=1800\r\n";
    }

    string clearSessionCookie() {
        return "Set-Cookie: session_id=; Path=/; HttpOnly; SameSite=Strict; Max-Age=0\r\n";
    }

    void handleClient(int client_fd) {
        char buffer[4096] = {0};
        ssize_t bytesRead = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytesRead <= 0) {
            close(client_fd);
            return;
        }

        string rawRequest(buffer, bytesRead);
        HttpRequest req = parseRequest(rawRequest);

        string response;
        map<string, string> headers;

        if (req.method == "POST" && req.path == "/login") {
            // Create new session
            string username = req.form_data.count("username") ? req.form_data["username"] : "anonymous";
            map<string, string> sessionData;
            sessionData["username"] = username;
            sessionData["login_time"] = to_string(duration_cast<seconds>(system_clock::now().time_since_epoch()).count());

            string sessionId = sessionManager.createSession(sessionData);

            string body = "<html><body><h1>Login Successful</h1><p>Welcome, " + username + "</p>";
            body += "<p><a href=\"/dashboard\">Go to Dashboard</a></p>";
            body += "<form method=\"POST\" action=\"/logout\"><button type=\"submit\">Logout</button></form>";
            body += "</body></html>";

            headers["Set-Cookie"] = "session_id=" + sessionId + "; Path=/; HttpOnly; SameSite=Strict; Max-Age=1800";
            response = buildResponse(200, "OK", "text/html", body, headers);

        } else if (req.method == "GET" && req.path == "/dashboard") {
            // Check session
            string sessionId;
            auto it = req.cookies.find("session_id");
            if (it != req.cookies.end()) sessionId = it->second;

            auto session = sessionManager.getSession(sessionId);
            if (session) {
                string username = session->data.count("username") ? session->data["username"] : "unknown";
                string body = "<html><body><h1>Dashboard</h1>";
                body += "<p>Welcome, " + username + "</p>";
                body += "<p>Session ID: " + session->id.substr(0, 8) + "...</p>";
                body += "<p>Session created: " + to_string(duration_cast<seconds>(session->created_at.time_since_epoch()).count()) + "</p>";
                body += "<form method=\"POST\" action=\"/logout\"><button type=\"submit\">Logout</button></form>";
                body += "</body></html>";
                response = buildResponse(200, "OK", "text/html", body);
            } else {
                string body = "<html><body><h1>Unauthorized</h1><p>Please <a href=\"/\">login</a></p></body></html>";
                response = buildResponse(401, "Unauthorized", "text/html", body);
            }

        } else if (req.method == "POST" && req.path == "/logout") {
            // Destroy session
            string sessionId;
            auto it = req.cookies.find("session_id");
            if (it != req.cookies.end()) {
                sessionManager.destroySession(it->second);
            }

            string body = "<html><body><h1>Logged Out</h1><p><a href=\"/\">Login again</a></p></body></html>";
            headers["Set-Cookie"] = "session_id=; Path=/; HttpOnly; SameSite=Strict; Max-Age=0";
            response = buildResponse(200, "OK", "text/html", body, headers);

        } else if (req.method == "GET" && req.path == "/") {
            // Home page with login form
            string body = "<html><body><h1>Session Manager</h1>";
            body += "<form method=\"POST\" action=\"/login\">";
            body += "<input type=\"text\" name=\"username\" placeholder=\"Username\" required>";
            body += "<button type=\"submit\">Login</button>";
            body += "</form></body></html>";
            response = buildResponse(200, "OK", "text/html", body);

        } else if (req.method == "GET" && req.path == "/api/session") {
            // API endpoint to check session status
            string sessionId;
            auto it = req.cookies.find("session_id");
            if (it != req.cookies.end()) sessionId = it->second;

            auto session = sessionManager.getSession(sessionId);
            if (session) {
                string json = "{\"authenticated\": true, \"username\": \"" +
                             (session->data.count("username") ? session->data["username"] : "unknown") +
                             "\", \"expires_in\": " + to_string(session->ttl_seconds) + "}";
                response = buildResponse(200, "OK", "application/json", json);
            } else {
                response = buildResponse(401, "Unauthorized", "application/json", "{\"authenticated\": false}");
            }

        } else {
            response = buildResponse(404, "Not Found", "text/html", "<html><body><h1>404 Not Found</h1></body></html>");
        }

        send(client_fd, response.c_str(), response.size(), 0);
        close(client_fd);
    }

    void cleanupThread() {
        while (running) {
            this_thread::sleep_for(seconds(60));
            sessionManager.cleanupExpired();
        }
    }

